inputs = ['jwdu', 'byya', 'hvv', 'hdx', 'zzw']
outputs = ['cwicwdu', 'byyd', 'dzyvv', 'dzydx', 'zzw']

# Analyze each transformation
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"Example {i}: '{inp}' -> '{outp}'")
    if inp != outp:
        # Find what changed
        min_len = min(len(inp), len(outp))
        diff_pos = -1
        for j in range(min_len):
            if inp[j] != outp[j]:
                diff_pos = j
                break

        if diff_pos == -1 and len(inp) != len(outp):
            diff_pos = min_len

        if diff_pos != -1:
            print(f"  Change at position {diff_pos}")
            if diff_pos < len(inp) and diff_pos < len(outp):
                print(f"  Old char: '{inp[diff_pos]}' -> New char: '{outp[diff_pos]}'")
            elif diff_pos < len(outp):
                print(f"  Added at pos {diff_pos}: '{outp[diff_pos]}'")
            else:
                print(f"  Removed at pos {diff_pos}: '{inp[diff_pos]}'")
        print()

